import{_ as e}from"./chunks/882956fbfd991e4b.BKxQldEz.js";import{_ as a,o,c as n,aa as r}from"./chunks/framework.D7Mdgkg-.js";const h=JSON.parse(`{"title":"Taxonomy","description":"Canonical Feluqa terms for products, applications, modules, platform instances, workspaces, and access control.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version English est affichée.","sidebarTitle":"Taxonomy","icon":"list-tree","title":"Taxonomy","description":"Canonical Feluqa terms for products, applications, modules, platform instances, workspaces, and access control.","summary":"Defines Feluqa's canonical distinctions among Products, Applications, Modules, Features, developer kit (SDK), Platform, projects, packages, runtimes, and access-control terms. Examples show how several applications can form one Product and how console interfaces relate to target profiles; the guide also sets naming rules and clarifies that target terminology does not promise completed features.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":3,"status":"Target","tags":["feluqa","taxonomy","vocabulary","glossary","sdk"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"fr/get-started/introduction/taxonomy.md","filePath":"fr/get-started/introduction/taxonomy.md"}`),i={name:"fr/get-started/introduction/taxonomy.md"};function s(d,t,c,l,p,u){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="taxonomy" tabindex="-1">Taxonomy <a class="header-anchor" href="#taxonomy" aria-label="Permalink to &quot;Taxonomy&quot;">​</a></h1><p>These terms describe different boundaries in Feluqa. <strong>Product</strong> names the solution people use. <strong>Application</strong> names a deployable program. <strong>Module</strong> names a reusable unit of business capability included in an application. They are related, but they are not interchangeable.</p><h2 id="product-and-runtime-boundaries" tabindex="-1">Product and runtime boundaries <a class="header-anchor" href="#product-and-runtime-boundaries" aria-label="Permalink to &quot;Product and runtime boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Product</strong></td><td>A solution offered to an organization or user, such as a bookstore system. A product may include several applications for different targets and user experiences. It is a business and packaging concept, not a runtime process.</td></tr><tr><td><strong>Application</strong></td><td>A Feluqa program composed for a particular execution role, such as a server application or a workstation application. It is built from one or more modules and produces target-specific artifacts. “App” is only an informal shortening of Application; it does not name a separate concept.</td></tr><tr><td><strong>Module</strong></td><td>A named unit of business capability, such as sales, inventory, or telemetry. An application includes one or more modules. Modules declare their own capabilities, permissions, configuration, and dependencies. A module is not itself an application or a product.</td></tr><tr><td><strong>Feature</strong></td><td>An optional capability within a module or application, enabled according to product configuration, license, or tenant policy.</td></tr><tr><td><strong>Target profile</strong></td><td>The constraints and runtime shape for a build, such as server, workstation, mobile, or embedded <code>no_std</code>. Separate target profiles may produce separate application artifacts from shared modules.</td></tr><tr><td><strong>Interaction surface</strong></td><td>How a person interacts with an application: a command-line interface, a graphical interface, or both. This is independent of the application&#39;s target profile.</td></tr><tr><td><strong>Host shell</strong></td><td>The runtime window or environment that presents an interaction surface. A workstation host could present a terminal as its primary interface or include a terminal within a graphical application. These host-shell options are product direction and are not implemented yet.</td></tr><tr><td><strong>Console application</strong></td><td>An application whose interaction model is based on commands and terminal input/output. It may run in a terminal or, as a future workstation product, inside a desktop host. “Console” describes the interaction model, not the Rust compilation target.</td></tr><tr><td><strong>Artifact</strong></td><td>A versioned build output for one application and target profile. Signing, installation, and dynamic module installation are target capabilities; they are not all implemented today.</td></tr><tr><td><strong>Application instance</strong></td><td>A running deployment of an application, with its own configuration, data, identity, and lifecycle. Multiple instances may serve different organizations or environments.</td></tr><tr><td><strong>Tenant</strong></td><td>An organization or isolated customer scope inside an application instance. A tenant is data and authorization context, not a device or a separate application.</td></tr></tbody></table><h3 id="example-one-product-two-applications" tabindex="-1">Example: one product, two applications <a class="header-anchor" href="#example-one-product-two-applications" aria-label="Permalink to &quot;Example: one product, two applications&quot;">​</a></h3><p>A bookstore product might contain a <strong>server application</strong> and a <strong>workstation application</strong>. Both can include shared catalog and inventory modules. The workstation communicates with the server through a defined API when connected; neither application needs to compile against the other&#39;s executable. A standalone workstation deployment can use its own local storage and defined synchronization behavior when that capability is implemented.</p><h3 id="example-console-interaction-on-a-workstation" tabindex="-1">Example: console interaction on a workstation <a class="header-anchor" href="#example-console-interaction-on-a-workstation" aria-label="Permalink to &quot;Example: console interaction on a workstation&quot;">​</a></h3><p>A console application can use a desktop host that opens a terminal-style window and presents the application&#39;s commands there. A different product could use a graphical desktop interface and include a terminal panel for console commands. In both cases, workstation is the target profile; terminal, graphical, or mixed describes the interaction surface. These are design examples, not current Feluqa features.</p><h2 id="feluqa-components" tabindex="-1">Feluqa components <a class="header-anchor" href="#feluqa-components" aria-label="Permalink to &quot;Feluqa components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Feluqa Platform</strong></td><td>The Feluqa-provided runtime and control plane: identity, access control, audit, configuration, and system administration. Its runtime capabilities vary by target profile.</td></tr><tr><td><strong>Platform instance</strong></td><td>One deployed installation of the Feluqa Platform. It administers its own system configuration and hosted application instances. This is the scope of platform-wide administration.</td></tr><tr><td><strong>System Control Panel</strong></td><td>The operator interface for administering a Platform instance and its registered applications and modules. It is a platform product, separate from business application panels.</td></tr><tr><td><strong>Feluqa developer kit (SDK)</strong></td><td>The Rust APIs and build tools used to create applications and modules.</td></tr><tr><td><strong>Feluqa CLI</strong></td><td>The command-line product for creating, developing, building, installing, and operating Feluqa projects and artifacts. Each command&#39;s implementation status is documented where that workflow is described.</td></tr><tr><td><strong>Project</strong></td><td>The source and configuration used to develop one or more applications and their modules. A project is a developer concept; it is not necessarily one deployable application.</td></tr><tr><td><strong>Workspace</strong></td><td>A Cargo-managed set of related Rust packages. A project may use a workspace when it needs more than one package.</td></tr><tr><td><strong>Crate</strong></td><td>A Rust compilation unit. A crate may implement part of an application, but it is not automatically a Feluqa Module.</td></tr><tr><td><strong>Package</strong></td><td>A Rust project unit described by a Cargo manifest. A package can contain a library, an executable, or both.</td></tr><tr><td><strong>Client</strong></td><td>A device or program that accesses an application, such as a browser, workstation, phone, or another service. A client is not a tenant.</td></tr></tbody></table><h2 id="application-building-blocks" tabindex="-1">Application building blocks <a class="header-anchor" href="#application-building-blocks" aria-label="Permalink to &quot;Application building blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Panel</strong></td><td>A user-facing surface provided by an application, such as an operator or business interface.</td></tr><tr><td><strong>Resource</strong></td><td>A typed business entity and its permitted operations, forms, tables, and policies.</td></tr><tr><td><strong>Page</strong></td><td>A screen within a panel, generated from a resource or implemented for a specific workflow.</td></tr><tr><td><strong>Service</strong></td><td>Application logic that performs business operations. UI visibility does not authorize a service action; the server checks access independently.</td></tr></tbody></table><h2 id="access-control-terms" tabindex="-1">Access-control terms <a class="header-anchor" href="#access-control-terms" aria-label="Permalink to &quot;Access-control terms&quot;">​</a></h2><p>Authorization uses separate scopes. <strong>Platform roles</strong> govern administration of a Platform instance. <strong>Application roles and permissions</strong> govern business actions. <strong>Policies</strong> apply record-specific rules. A platform-wide rank does not grant business permissions by itself.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Platform owner</strong></td><td>The single highest-authority principal for one Platform instance. The target identifier is <code>platform-owner</code>; the old <code>app-owner</code> name is retired because it incorrectly suggests ownership of a business application.</td></tr><tr><td><strong>Privilege level</strong></td><td>A rank used for platform-instance administration, such as <code>platform-owner</code>, <code>super-admin</code>, <code>sysadmin</code>, or <code>staff</code>. It does not grant application permissions by itself.</td></tr><tr><td><strong>Origin</strong></td><td>Whether an administrative account is internal to the operating organization or external, such as an auditor or contractor. Origin is separate from privilege level.</td></tr><tr><td><strong>Permission</strong></td><td>An atomic application capability, such as <code>sales.refund</code> or <code>sales.customers.delete</code>.</td></tr><tr><td><strong>Application role</strong></td><td>A named set of application permissions assignable within the relevant application and tenant scope.</td></tr><tr><td><strong>Policy</strong></td><td>A rule that decides whether an otherwise authorized action applies to a particular record.</td></tr><tr><td><strong>Gate</strong></td><td>A server-side enforcement point that checks the required identity, privilege, permission, and policy conditions before an action runs.</td></tr><tr><td><strong>Clearance</strong></td><td>An exploring classification label that may add data-handling constraints in high-security deployments.</td></tr></tbody></table><p>These are the target names and boundaries. Feluqa does not preserve confusing legacy names for backward compatibility. Renaming an implemented identifier requires changing its API, stored data, CLI output, and documentation together; the target terminology does not claim that migration is already complete.</p><h2 id="how-the-terms-fit-together" tabindex="-1">How the terms fit together <a class="header-anchor" href="#how-the-terms-fit-together" aria-label="Permalink to &quot;How the terms fit together&quot;">​</a></h2><p><img src="'+e+'" alt="Mermaid diagram"></p><h2 id="naming-rule" tabindex="-1">Naming rule <a class="header-anchor" href="#naming-rule" aria-label="Permalink to &quot;Naming rule&quot;">​</a></h2><p>Use <strong>Product</strong> for the solution being offered, <strong>Application</strong> for a program that is built and run, and <strong>Module</strong> for a reusable business capability included in an application. Use <strong>Platform instance</strong> for the administrative scope that owns platform-wide privileges. Avoid using <code>app</code>, <code>product</code>, and <code>module</code> as synonyms in code, manifests, CLI commands, or documentation.</p><p>For authorization details, see the <a href="/fr/security/authorization-model">authorization model</a> and <a href="/fr/security/privilege-levels">privilege levels</a>.</p>',21)])])}const f=a(i,[["render",s]]);export{h as __pageData,f as default};
